            src={product.image}
            alt={product.title}
            className="w-full h-48 object-cover group-hover:scale-105 transition-transform duration-300"
          />
          <Badge className={`absolute top-3 left-3 ${categoryColors[product.category]}`}>
            {t(`categories.${product.category}`)}
          </Badge>
        </div>
