// hooks/usePiAuth.ts
import { useState, useEffect, useCallback } from 'react';

interface PiUser {
  uid: string;
  username: string;
}

export function usePiAuth() {
  const [user, setUser] = useState<PiUser | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const authenticate = useCallback(async () => {
    setIsLoading(true);
    try {
      const scopes = ['username', 'payments'];
      const auth = await window.Pi.authenticate(scopes, onIncompletePaymentFound);

      // Vérifier côté serveur via /me endpoint
      const response = await fetch('/api/auth/pi', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ accessToken: auth.accessToken })
      });

      const userData = await response.json();
      setUser(userData);
      localStorage.setItem('pipolis_user', JSON.stringify(userData));
    } catch (err) {
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const onIncompletePaymentFound = useCallback((payment: any) => {
    console.log('Payment incomplet trouvé:', payment);
    // Gérer le paiement incomplet côté serveur
  }, []);

  const logout = useCallback(() => {
    setUser(null);
    localStorage.removeItem('pipolis_user');
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem('pipolis_user');
    if (saved) setUser(JSON.parse(saved));
  }, []);

  return { user, authenticate, logout, isLoading, error };
}
