// routes/auth.js
const axios = require('axios');
const User = require('../models/User');

router.post('/auth/pi', async (req, res) => {
  const { accessToken } = req.body;

  try {
    // Vérifier le token avec Pi Server
    const piResponse = await axios.get('https://api.minepi.com/v2/me', {
      headers: { Authorization: `Bearer ${accessToken}` }
    });

    const { uid, username } = piResponse.data;

    // Créer ou mettre à jour l'utilisateur
    let user = await User.findOne({ piUid: uid });
    if (!user) {
      user = new User({ piUid: uid, username });
      await user.save();
    }

    res.json({ uid, username, reputation: user.reputation });
  } catch (error) {
    res.status(401).json({ error: 'Authentification Pi invalide' });
  }
});
