JOUR 10 — Smart Contract Governance (PiRC2)
Action : Enregistrer les votes on-chain avec preuve immuable
// contracts/PiPolisGovernance.js
class PiPolisGovernance {
  constructor() {
    this.proposals = new Map(); // proposalId -> { votes, weights, status }
    this.voteHistory = new Map(); // userUid -> [proposalIds]
  }

  async createProposal(projectId, title, description, deadline) {
    const proposalId = `prop_${Date.now()}_${projectId}`;

    const proposal = await PiRC2.createGovernanceContract({
      type: 'proposal',
      metadata: { projectId, title, description },
      votingPeriod: { start: Date.now(), end: deadline },
      quorum: 0.05, // 5% des votants actifs minimum
      threshold: 0.66, // 66% pour approbation
      options: ['for', 'against', 'abstain']
    });

    this.proposals.set(proposalId, {
      contractId: proposal.contractId,
      votes: { for: 0, against: 0, abstain: 0 },
      voters: [],
      status: 'active',
      deadline
    });

    return proposalId;
  }

  async vote(proposalId, userUid, vote, weight) {
    // Vérifier que l'utilisateur n'a pas déjà voté
    const userVotes = this.voteHistory.get(userUid) || [];
    if (userVotes.includes(proposalId)) {
      throw new Error('User already voted on this proposal');
    }

    const proposal = this.proposals.get(proposalId);
    if (Date.now() > proposal.deadline) {
      throw new Error('Voting period ended');
    }

    // Enregistrer le vote on-chain
    await PiRC2.recordVote({
      contractId: proposal.contractId,
      voter: userUid,
      option: vote,
      weight,
      timestamp: Date.now()
    });

    proposal.votes[vote] += weight;
    proposal.voters.push({ uid: userUid, vote, weight, timestamp: Date.now() });
    userVotes.push(proposalId);
    this.voteHistory.set(userUid, userVotes);

    return { proposalId, vote, weight };
  }

  async finalizeProposal(proposalId) {
    const proposal = this.proposals.get(proposalId);
    const totalVotes = proposal.votes.for + proposal.votes.against + proposal.votes.abstain;
    const totalWeight = proposal.votes.for + proposal.votes.against;

    // Vérifier quorum
    const activePioneers = await getActivePioneersCount(); // API Pi
    if (totalVotes / activePioneers < proposal.quorum) {
      proposal.status = 'failed_quorum';
      return { status: 'failed', reason: 'quorum_not_met' };
    }

    // Vérifier threshold
    if (proposal.votes.for / totalWeight >= proposal.threshold) {
      proposal.status = 'approved';
      // Déclencher le financement via escrow
      await PiRC2.executeProposal(proposal.contractId);
      return { status: 'approved', for: proposal.votes.for, against: proposal.votes.against };
    } else {
      proposal.status = 'rejected';
      return { status: 'rejected', for: proposal.votes.for, against: proposal.votes.against };
    }
  }
}

module.exports = PiPolisGovernance;
