import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { createClient } from '@metagptx/web-sdk';
import { getCurrentUser } from '@/lib/pi-sdk';

const client = createClient();

interface Comment {
  id: number;
  project_id: number;
  content: string;
  pi_uid: string;
  pi_username: string;
  parent_id: number | null;
  likes: number;
  created_at: string | null;
}

interface CommentsProps {
  projectId: number;
}

export default function Comments({ projectId }: CommentsProps) {
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState('');
  const [replyTo, setReplyTo] = useState<number | null>(null);
  const [replyContent, setReplyContent] = useState('');
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const user = getCurrentUser();

  useEffect(() => {
    loadComments();
  }, [projectId]);

  const loadComments = async () => {
    setLoading(true);
    try {
      const response = await client.apiCall.invoke({
        url: `/api/v1/entities/comments/all?query=${encodeURIComponent(JSON.stringify({ project_id: projectId }))}&sort=-created_at&limit=50`,
        method: 'GET',
      });
      if (response?.data?.items) {
        setComments(response.data.items);
      }
    } catch (err) {
      console.error('Failed to load comments:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.trim() || !user) return;

    setSubmitting(true);
    try {
      await client.apiCall.invoke({
        url: '/api/v1/entities/comments',
        method: 'POST',
        data: {
          project_id: projectId,
          content: newComment.trim(),
          pi_uid: user.uid,
          pi_username: user.username,
          parent_id: null,
          likes: 0,
        },
      });
      setNewComment('');
      await loadComments();
    } catch (err) {
      console.error('Failed to post comment:', err);
    } finally {
      setSubmitting(false);
    }
  };

  const handleReply = async (parentId: number) => {
    if (!replyContent.trim() || !user) return;

    setSubmitting(true);
    try {
      await client.apiCall.invoke({
        url: '/api/v1/entities/comments',
        method: 'POST',
        data: {
          project_id: projectId,
          content: replyContent.trim(),
          pi_uid: user.uid,
          pi_username: user.username,
          parent_id: parentId,
          likes: 0,
        },
      });
      setReplyTo(null);
      setReplyContent('');
      await loadComments();
    } catch (err) {
      console.error('Failed to post reply:', err);
    } finally {
      setSubmitting(false);
    }
  };

  const handleLike = async (commentId: number, currentLikes: number) => {
    try {
      await client.apiCall.invoke({
        url: `/api/v1/entities/comments/${commentId}`,
        method: 'PUT',
        data: { likes: currentLikes + 1 },
      });
      setComments((prev) =>
        prev.map((c) => (c.id === commentId ? { ...c, likes: c.likes + 1 } : c))
      );
    } catch (err) {
      console.error('Failed to like comment:', err);
    }
  };

  const topLevelComments = comments.filter((c) => !c.parent_id);
  const getReplies = (parentId: number) => comments.filter((c) => c.parent_id === parentId);

  const formatDate = (dateStr: string | null) => {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 1) return 'À l\'instant';
    if (diffMins < 60) return `Il y a ${diffMins}min`;
    if (diffHours < 24) return `Il y a ${diffHours}h`;
    if (diffDays < 7) return `Il y a ${diffDays}j`;
    return date.toLocaleDateString('fr-FR');
  };

  return (
    <div className="mt-8">
      <h3 className="text-xl font-bold text-white mb-4 flex items-center gap-2">
        💬 Discussion
        <span className="text-sm font-normal text-gray-400">({comments.length})</span>
