                  {user && (
                    <button
                      onClick={() => setReplyTo(replyTo === comment.id ? null : comment.id)}
                      className="text-xs text-gray-500 hover:text-indigo-400 transition-colors"
                    >
                      ↩️ Répondre
                    </button>
                  )}
                </div>

                {/* Reply Form */}
                {replyTo === comment.id && (
                  <motion.div
                    initial={{ opacity: 0, height: 0 }}
