import { Toaster } from '@/components/ui/sonner';
import { TooltipProvider } from '@/components/ui/tooltip';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import { autoAuthenticate, isInPiBrowser } from '@/lib/pi-sdk';
import Index from './pages/Index';
import Proposals from './pages/Proposals';
import ProposalDetail from './pages/ProposalDetail';
import CreateProposal from './pages/CreateProposal';
import Funding from './pages/Funding';
import Dashboard from './pages/Dashboard';
import Quests from './pages/Quests';
import AuthCallback from './pages/AuthCallback';
import Privacy from './pages/Privacy';
import Terms from './pages/Terms';

const queryClient = new QueryClient();

const AppRoutes = () => (
  <Routes>
    <Route path="/" element={<Index />} />
    <Route path="/proposals" element={<Proposals />} />
    <Route path="/proposal/:id" element={<ProposalDetail />} />
    <Route path="/create" element={<CreateProposal />} />
    <Route path="/funding" element={<Funding />} />
    <Route path="/dashboard" element={<Dashboard />} />
    <Route path="/quests" element={<Quests />} />
    <Route path="/auth/callback" element={<AuthCallback />} />
    <Route path="/privacy" element={<Privacy />} />
    <Route path="/terms" element={<Terms />} />
  </Routes>
);

const App = () => {
  const [ready, setReady] = useState(!isInPiBrowser());

  useEffect(() => {
    // Auto-authenticate when running inside Pi Browser
    // This detects the Pioneer's Pi username automatically
    if (isInPiBrowser()) {
      autoAuthenticate().finally(() => setReady(true));
    }
  }, []);

  if (!ready) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mx-auto mb-4" />
          <p className="text-indigo-300 text-lg font-medium">Connexion à Pi Network...</p>
          <p className="text-gray-500 text-sm mt-2">Détection de votre profil Pionnier</p>
        </div>
      </div>
    );
  }

  return (
    <QueryClientProvider client={queryClient}>
      <TooltipProvider>
        <Toaster />
        <BrowserRouter>
          <AppRoutes />
        </BrowserRouter>
      </TooltipProvider>
    </QueryClientProvider>
  );
};

export default App;
export { AppRoutes };</new_string>
