          badges: [],
          level: 'bronze',
          piLocked: 0,
          streakDays: 0,
          kycVerified: false,
          language: 'fr'
        };
      }

      localStorage.setItem('poligov_user', JSON.stringify(currentUser));
      notifyListeners();
      return currentUser;
    } catch (error) {
