                            'bg-blue-500/20 text-blue-400'
                          }`}>{log.action}</span>
                          <span className="text-gray-300 flex-1">{log.target}</span>
                          <span className="text-gray-500 text-xs">{new Date(log.timestamp).toLocaleString()}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              )}

              {/* Projects Tab */}
              {activeTab === 'projects' && (
                <div className="space-y-4">
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="text-white font-semibold">Modération des projets</h3>
                    <span className="text-xs text-gray-400">{projects.length} projets au total</span>
                  </div>
                  {projects.map((project) => (
                    <motion.div
