            <div className="text-center p-3">
              <span className="text-2xl block mb-2">🔄</span>
              <p className="text-sm text-gray-300 font-medium">Révoquez à tout moment</p>
              <p className="text-xs text-gray-500 mt-1">Reprenez votre pouvoir de vote instantanément si nécessaire</p>
            </div>
          </div>
        </div>
      </div>

      {/* Delegate Modal */}
      {showDelegateModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm" onClick={() => setShowDelegateModal(false)}>
          <motion.div
            className="bg-slate-800 border border-slate-700 rounded-2xl p-6 w-full max-w-md mx-4"
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
