// services/piPaymentService.js
const StellarSdk = require('stellar-sdk');
const axios = require('axios');

const PI_TESTNET = 'https://api.testnet.minepi.com';
const PI_MAINNET = 'https://api.mainnet.minepi.com';
const NETWORK = process.env.NODE_ENV === 'production' ? 'Pi Network' : 'Pi Testnet';
const SERVER_URL = process.env.NODE_ENV === 'production' ? PI_MAINNET : PI_TESTNET;

const server = new StellarSdk.Server(SERVER_URL);
const PI_API_KEY = process.env.PI_API_KEY;
const DEVELOPER_SEED = process.env.DEVELOPER_SECRET_SEED; // ⚠️ JAMAIS en clair
const DEVELOPER_PUBLIC = process.env.DEVELOPER_PUBLIC_KEY;

class PiPaymentService {
  async createA2UPayment(userUid, amount, memo) {
    // 1. Créer le paiement via API Pi
    const axiosClient = axios.create({
      baseURL: 'https://api.minepi.com',
      headers: {
        'Authorization': `Key ${PI_API_KEY}`,
        'Content-Type': 'application/json'
      }
    });

    const body = {
      amount,
      memo,
      metadata: { type: 'reward' },
      uid: userUid
    };

    const response = await axiosClient.post('/v2/payments', body);
    const { identifier: paymentId, recipient: recipientAddress } = response.data;

    // 2. Charger le compte développeur
    const account = await server.loadAccount(DEVELOPER_PUBLIC);
    const baseFee = await server.fetchBaseFee();
    const timebounds = await server.fetchTimebounds(180);

    // 3. Construire la transaction
    const payment = StellarSdk.Operation.payment({
      destination: recipientAddress,
      asset: StellarSdk.Asset.native(),
      amount: amount.toString()
    });

    const transaction = new StellarSdk.TransactionBuilder(account, {
      fee: baseFee,
      networkPassphrase: NETWORK,
      timebounds
    })
    .addOperation(payment)
    .addMemo(StellarSdk.Memo.text(paymentId))
    .build();

    // 4. Signer
    const keypair = StellarSdk.Keypair.fromSecret(DEVELOPER_SEED);
    transaction.sign(keypair);

    // 5. Soumettre
    const result = await server.submitTransaction(transaction);
    const txid = result.id;

    // 6. Compléter
    await axiosClient.post(`/v2/payments/${paymentId}/complete`, { txid });

    return { paymentId, txid, status: 'completed' };
  }
}

module.exports = new PiPaymentService();
