Structure du contrat (pseudo-code basé sur PiRC2) :
// contracts/PiPolisEscrow.js
// Ce contrat verrouille les fonds et les libère par milestones

const PiRC2 = require('pirc2-sdk'); // SDK hypothétique PiRC2

class PiPolisEscrow {
  constructor(projectId, totalBudget, milestones) {
    this.projectId = projectId;
    this.totalBudget = totalBudget;
    this.milestones = milestones; // [{ title, amount, validator }]
    this.funded = false;
    this.completedMilestones = 0;
    this.contributors = []; // [{ uid, amount, timestamp }]
  }

  async fund(userUid, amount) {
    // Vérifier que le projet n'est pas déjà financé
    if (this.funded) throw new Error('Project already funded');

    // Créer paiement U2A vers l'adresse escrow
    const payment = await PiRC2.createPayment({
      to: this.escrowAddress,
      amount,
      memo: `Fund:${this.projectId}`,
      lockUntil: this.milestones[this.milestones.length - 1].deadline
    });

    this.contributors.push({ uid: userUid, amount, timestamp: Date.now() });

    // Si budget atteint, verrouiller
    const total = this.contributors.reduce((sum, c) => sum + c.amount, 0);
    if (total >= this.totalBudget) {
      this.funded = true;
      await PiRC2.lockFunds(this.escrowAddress, this.totalBudget);
    }

    return payment;
  }

  async releaseMilestone(milestoneIndex, proofHash) {
    // Vérifier que le milestone précédent est complété
    if (milestoneIndex !== this.completedMilestones) {
      throw new Error('Milestones must be completed in order');
    }

    const milestone = this.milestones[milestoneIndex];

    // Vérifier la preuve (par le validator ou vote DAO)
    const isValid = await PiRC2.verifyProof(proofHash, milestone.validator);
    if (!isValid) throw new Error('Proof validation failed');

    // Libérer les fonds au créateur du projet
    await PiRC2.release(
      this.escrowAddress,
      milestone.amount,
      milestone.creatorAddress,
      `Milestone:${milestoneIndex}:${proofHash}`
    );

    this.completedMilestones++;

    // Si tous les milestones complétés, libérer le reste
    if (this.completedMilestones === this.milestones.length) {
      await PiRC2.closeEscrow(this.escrowAddress);
    }

    return { released: milestone.amount, milestoneIndex };
  }

  async refund() {
    // Si deadline dépassée et projet non complété → remboursement proportionnel
    if (Date.now() < this.milestones[this.milestones.length - 1].deadline) {
      throw new Error('Deadline not reached');
    }

    for (const contributor of this.contributors) {
      const refundAmount = (contributor.amount / this.totalBudget) * this.getRemainingBalance();
      await PiRC2.release(this.escrowAddress, refundAmount, contributor.uid, 'Refund');
    }
  }
}

module.exports = PiPolisEscrow;
