// contracts/PiPolisReputation.js
class PiPolisReputation {
  constructor() {
    this.reputationFormula = {
      piLocked: 0.4,
      votesCast: 0.3,
      projectsFunded: 0.2,
      tenure: 0.1
    };
  }

  async calculateReputation(userUid) {
    const user = await User.findOne({ piUid: userUid });

    // Récupérer les données on-chain
    const onChainData = await PiRC2.getUserActivity(userUid);

    const reputation = 
      (onChainData.piLocked * this.reputationFormula.piLocked) +
      (onChainData.votesCast * this.reputationFormula.votesCast) +
      (onChainData.projectsFunded * this.reputationFormula.projectsFunded) +
      (onChainData.tenureDays * this.reputationFormula.tenure);

    // Déterminer le niveau
    let level = 'bronze';
    if (reputation > 1000) level = 'silver';
    if (reputation > 5000) level = 'gold';
    if (reputation > 20000) level = 'diamond';
    if (reputation > 100000) level = 'platinum';

    // Mettre à jour on-chain
    await PiRC2.updateReputation(userUid, {
      score: reputation,
      level,
      updatedAt: Date.now()
    });

    return { score: reputation, level };
  }

  async getVoteWeight(userUid) {
    const rep = await PiRC2.getReputation(userUid);
    // Poids logarithmique pour éviter la domination des whales
    return Math.log10(rep.score + 10) * 10;
  }
}

module.exports = PiPolisReputation;
