// middleware.ts
import { NextRequest, NextResponse } from 'next/server';

export function middleware(request: NextRequest) {
  const locale = request.headers.get('accept-language')?.split(',')[0].split('-')[0] || 'fr';
  const validLocale = locales.includes(locale) ? locale : 'fr';

  return NextResponse.rewrite(new URL(`/${validLocale}${request.nextUrl.pathname}`, request.url));
}

