router.get('/api/v1/projects', async (req, res) => {
  const { status, category, page = 1, limit = 20 } = req.query;

  const query = {};
  if (status) query.status = status;
  if (category) query.category = category;

  const projects = await Project.find(query)
    .select('-transactionIds -escrowContractId') // Masquer données sensibles
    .sort({ createdAt: -1 })
    .skip((page - 1) * limit)
    .limit(limit);

  res.json({
    projects,
    pagination: { page, limit, total: await Project.countDocuments(query) }
  });
});

router.get('/api/v1/projects/:id', async (req, res) => {
  const project = await Project.findById(req.params.id)
    .select('-transactionIds');
  res.json(project);
});

router.get('/api/v1/stats', async (req, res) => {
  const stats = {
    totalProjects: await Project.countDocuments(),
    totalFunded: await Project.aggregate([{ $group: { _id: null, total: { $sum: '$raised' } } }]),
    totalVotes: await Project.aggregate([{ $group: { _id: null, total: { $sum: { $add: ['$votes.for', '$votes.against'] } } } }]),
    activePioneers: await User.countDocuments()
  };
  res.json(stats);
});

