      } else {
        setStatus('Authentification réussie');
        setTimeout(() => navigate('/'), 1500);
      }
    } catch (error) {
      console.error('[PoliGov] Auth callback error:', error);
      setStatus('Erreur d\'authentification. Redirection...');
      setTimeout(() => navigate('/'), 2000);
